const healthAliases={
        observedOn:['date','calendarDate','calendar_date','startTime','start_time','timestamp','timeCreated'],
        steps:['steps','totalSteps','total_steps','stepCount','step_count','dailySteps','cumulativeSteps'],
        stepGoal:['stepGoal','step_goal','stepsGoal','steps_goal','dailyStepGoal','goalSteps'],
        sleepMinutes:['sleepMinutes','sleep_minutes','totalSleepMinutes','total_sleep_minutes','sleepDurationMinutes'],
        sleepSeconds:['sleepSeconds','sleep_seconds','totalSleepSeconds','total_sleep_seconds','sleepTimeSeconds','durationInSeconds'],
        activeCalories:['activeCalories','active_calories','activeKilocalories','active_kilocalories','activityCalories'],
        totalCalories:['totalCalories','total_calories','totalKilocalories','total_kilocalories','calories'],
        restingHeartRate:['restingHeartRate','resting_heart_rate','restingHr','resting_hr'],
        averageHeartRate:['averageHeartRate','average_heart_rate','avgHeartRate','avg_heart_rate','heartRateAvg'],
        stressAverage:['stressAverage','stress_average','averageStressLevel','average_stress_level','avgStress','stress'],
        hrvMs:['hrvMs','hrv_ms','hrv','hrvStatus','lastNightAvg','weeklyAvg'],
        activityName:['activityName','activity_name','name','title'], activityType:['activityType','activity_type','sport','subSport'],
        activityDuration:['activityDurationMinutes','activity_duration_minutes','durationMinutes','totalTimerTime','totalElapsedTime'],
        activityDistance:['activityDistanceKm','activity_distance_km','distanceKm','totalDistance','distance']
      };
      const normalizedKey=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]/g,'').toLowerCase();
      const aliasSets=Object.fromEntries(Object.entries(healthAliases).map(([name,values])=>[name,new Set(values.map(normalizedKey))]));
      const finiteNumber=value=>{if(typeof value==='number')return Number.isFinite(value)?value:null;const parsed=Number(String(value??'').replace(/\s/g,'').replace(',','.').replace(/[^0-9.+-]/g,''));return Number.isFinite(parsed)?parsed:null};
      const valueFor=(object,alias)=>{if(!object||typeof object!=='object')return null;for(const [key,value] of Object.entries(object)){if(aliasSets[alias].has(normalizedKey(key))&&value!==''&&value!==null&&value!==undefined)return value}return null};
      function collectHealthObjects(value,result=[],depth=0){if(depth>8||value===null||typeof value!=='object')return result;if(Array.isArray(value)){value.forEach(item=>collectHealthObjects(item,result,depth+1));return result;}result.push(value);Object.values(value).forEach(item=>collectHealthObjects(item,result,depth+1));return result;}
      function parseObservedDate(value){if(value instanceof Date&&!Number.isNaN(value.valueOf()))return value.toISOString().slice(0,10);if(value===null||value===undefined)return null;const text=String(value);const direct=text.match(/(20\d{2})[-/]([01]?\d)[-/]([0-3]?\d)/);if(direct)return `${direct[1]}-${String(direct[2]).padStart(2,'0')}-${String(direct[3]).padStart(2,'0')}`;const date=new Date(text);return Number.isNaN(date.valueOf())?null:date.toISOString().slice(0,10)}
      function candidateFromObject(object){const sleepMinutes=finiteNumber(valueFor(object,'sleepMinutes'));const sleepSeconds=finiteNumber(valueFor(object,'sleepSeconds'));const activityDuration=finiteNumber(valueFor(object,'activityDuration'));const rawDistance=finiteNumber(valueFor(object,'activityDistance'));const raw={
        observedOn:parseObservedDate(valueFor(object,'observedOn')),steps:finiteNumber(valueFor(object,'steps')),stepGoal:finiteNumber(valueFor(object,'stepGoal')),
        sleepMinutes:sleepMinutes??(sleepSeconds===null?null:Math.round(sleepSeconds/60)),activeCalories:finiteNumber(valueFor(object,'activeCalories')),totalCalories:finiteNumber(valueFor(object,'totalCalories')),
        restingHeartRate:finiteNumber(valueFor(object,'restingHeartRate')),averageHeartRate:finiteNumber(valueFor(object,'averageHeartRate')),stressAverage:finiteNumber(valueFor(object,'stressAverage')),hrvMs:finiteNumber(valueFor(object,'hrvMs'))
      };const activityName=valueFor(object,'activityName');const activityType=valueFor(object,'activityType');if(activityName||activityType||activityDuration!==null||rawDistance!==null)raw.latestActivity={name:String(activityName||activityType||'Activité Garmin'),type:String(activityType||''),durationMinutes:activityDuration===null?null:(activityDuration>600?Math.round(activityDuration/60):Math.round(activityDuration)),distanceKm:rawDistance===null?null:Number((rawDistance>1000?rawDistance/1000:rawDistance).toFixed(2))};return raw;}
      function mergeHealthSummaries(summaries){const merged={};const numeric=['steps','stepGoal','sleepMinutes','activeCalories','totalCalories','restingHeartRate','averageHeartRate','stressAverage','hrvMs'];const sorted=summaries.filter(Boolean).sort((a,b)=>String(a.observedOn||'').localeCompare(String(b.observedOn||'')));for(const summary of sorted){if(summary.observedOn)merged.observedOn=summary.observedOn;numeric.forEach(key=>{if(summary[key]!==null&&summary[key]!==undefined&&Number.isFinite(Number(summary[key])))merged[key]=Math.round(Number(summary[key])*10)/10});if(summary.latestActivity)merged.latestActivity=summary.latestActivity}return merged;}
      function extractHealthSummary(payload){const candidates=collectHealthObjects(payload).map(candidateFromObject);const merged=mergeHealthSummaries(candidates);if(payload?.hrvMesgs){const values=payload.hrvMesgs.flatMap(message=>Array.isArray(message.time)?message.time:[]).map(finiteNumber).filter(value=>value!==null&&value>0&&value<500);if(values.length)merged.hrvMs=Math.round(values.reduce((sum,value)=>sum+value,0)/values.length)}return merged;}
      function parseDelimited(text){const first=(text.split(/\r?\n/).find(line=>line.trim())||'');const delimiters=[',',';','\t'];const delimiter=delimiters.sort((a,b)=>first.split(b).length-first.split(a).length)[0];const rows=[];let row=[];let field='';let quoted=false;for(let index=0;index<text.length;index++){const char=text[index];if(char==='"'){if(quoted&&text[index+1]==='"'){field+='"';index++;}else quoted=!quoted;}else if(char===delimiter&&!quoted){row.push(field.trim());field='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[index+1]==='\n')index++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=char;}row.push(field.trim());if(row.some(Boolean))rows.push(row);if(rows.length<2)return [];const headers=rows[0].map((header,index)=>header||`colonne_${index+1}`);return rows.slice(1).map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]??''])));}
      let zipLoader;function loadZip(){if(window.JSZip)return Promise.resolve(window.JSZip);if(zipLoader)return zipLoader;zipLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';script.onload=()=>resolve(window.JSZip);script.onerror=()=>reject(new Error('Lecteur ZIP indisponible'));document.head.appendChild(script)});return zipLoader;}
      async function parseFitData(file){const sdk=await import('https://cdn.jsdelivr.net/npm/@garmin/fitsdk@21.214.0/+esm');const bytes=new Uint8Array(await file.arrayBuffer());const stream=sdk.Stream.fromByteArray(Array.from(bytes));if(!sdk.Decoder.isFIT(stream))throw new Error('Ce fichier ne possède pas un en-tête FIT valide.');const decoder=new sdk.Decoder(stream);const decoded=decoder.read({convertDateTimesToDates:true,mergeHeartRates:true});if(decoded.errors?.length&&!decoded.messages)throw new Error(decoded.errors[0]);return extractHealthSummary(decoded.messages||{});}
      async function parseHealthFile(file){const extension=(file.name.split('.').pop()||'').toLowerCase();if(extension==='fit')return parseFitData(file);if(extension==='zip'){const JSZip=await loadZip();const archive=await JSZip.loadAsync(file);const summaries=[];for(const entry of Object.values(archive.files)){if(entry.dir||!/[.](fit|csv|json)$/i.test(entry.name))continue;try{if(/[.]fit$/i.test(entry.name)){summaries.push(await parseFitData(await entry.async('blob')));continue;}const text=await entry.async('string');summaries.push(extractHealthSummary(/[.]json$/i.test(entry.name)?JSON.parse(text):parseDelimited(text)));}catch(error){}}if(!summaries.length)throw new Error('Aucun fichier FIT, CSV ou JSON exploitable trouvé dans cette archive.');return mergeHealthSummaries(summaries);}const text=await file.text();if(extension==='json')return extractHealthSummary(JSON.parse(text));if(extension==='csv'||file.type.includes('csv')||file.type.startsWith('text/'))return extractHealthSummary(parseDelimited(text));throw new Error('Format non reconnu. Utilisez un fichier FIT, CSV, JSON ou ZIP.');}
